// CAMPAIGN GATE  (Code node, "Run Once for All Items")
// Fail-closed: the run proceeds ONLY if every check below passes.
// Quiet blocks (draft/completed/before send time...) end silently.
// "Attention" blocks flag the campaign row and raise an execution error (-> error workflow e-mail).

const cfg = $('Workflow Config').first().json;
const tz = String(cfg.timezone || 'Asia/Kathmandu');
const now = DateTime.now().setZone(tz);
const runId = `${now.toFormat("yyyyLLdd'T'HHmmss")}-${$execution.id ?? 'x'}`;
const dryRun = cfg.dryRun !== false; // anything other than an explicit boolean false = dry run

const base = {
  proceed: false, reason: '', needsAttention: false, flagStatus: '', flagNote: '',
  campaignId: String(cfg.campaignId || '').trim(), dryRun, runId, nowIso: now.toISO(),
};
const quiet = (reason, extra = {}) => [{ json: { ...base, reason, ...extra } }];
const alert = (reason, flagStatus, note) =>
  [{ json: { ...base, reason, needsAttention: true, flagStatus: flagStatus || '', flagNote: String(note || reason).slice(0, 300) } }];

const nonEmpty = (r) => r && Object.values(r).some((v) => String(v ?? '').trim() !== '');
const rows = $input.all().map((i) => i.json).filter(nonEmpty);
const str = (v) => String(v ?? '').trim();
const isPlaceholder = (v) => str(v) === '' || /^REPLACE/i.test(str(v));

// ---------- 0. workflow configuration sanity ----------
if (!base.campaignId || isPlaceholder(base.campaignId)) {
  return alert('config_campaign_id_not_set', '', 'campaignId is not configured in the Workflow Config node');
}

// ---------- 1. campaign row ----------
if (rows.length === 0) return alert('campaign_row_not_found', '', 'No row in the Campaigns sheet matches the configured campaign_id');
if (rows.length > 1) return alert('multiple_campaign_rows', 'paused', 'More than one Campaigns row has this campaign_id');
const c = rows[0];
const status = str(c.approval_status || c.status || c.campaign_status).toLowerCase();

// ---------- 2. status guard ----------
if (status === 'running') {
  const staleMin = Number(cfg.staleLockMinutes ?? 90);
  const last = DateTime.fromISO(str(c.last_run_at), { setZone: true });
  if (last.isValid && now.diff(last, 'minutes').minutes > staleMin) {
    return alert('stale_running_lock', 'paused',
      `Campaign has been 'running' for more than ${staleMin} min (last_run_at ${last.toISO()}). A previous run may have crashed or n8n restarted. Review rows with status processing/unknown BEFORE re-approving.`);
  }
  return quiet('campaign_status_running');
}
const QUIET = ['', 'draft', 'completed', 'disabled', 'paused', 'expired'];
if (QUIET.includes(status)) return quiet(`campaign_status_${status || 'blank'}`);
if (status !== 'approved') {
  return alert('campaign_status_unrecognised', 'paused',
    `Unrecognised campaign status "${status.slice(0, 30)}". Allowed: draft, approved, running, completed, disabled, paused, expired.`);
}
if (String(c.active ?? 'true').toLowerCase() === 'false' || ['no','0','inactive'].includes(str(c.active).toLowerCase())) return quiet('campaign_inactive');
if (!str(c.approved_by)) return alert('approved_by_missing', 'paused', 'Status is approved but approved_by is empty.');

// ---------- 3. send date / time (Asia/Kathmandu) ----------
const toDateStr = (v) => {
  if (typeof v === 'number' && isFinite(v)) { // Google Sheets serial date
    return DateTime.fromMillis(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000, { zone: 'utc' }).toFormat('yyyy-LL-dd');
  }
  return str(v);
};
const toTimeStr = (v) => {
  if (typeof v === 'number' && isFinite(v)) { // fraction of a day
    const mins = Math.round(v * 1440);
    return String(Math.floor(mins / 60) % 24).padStart(2, '0') + ':' + String(mins % 60).padStart(2, '0');
  }
  const m = str(v).match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  return m ? m[1].padStart(2, '0') + ':' + m[2] : str(v);
};
const sendDate = toDateStr(c.scheduled_date || c.send_date);
const sendTime = toTimeStr(c.scheduled_time || c.send_time);
const sendAt = DateTime.fromFormat(`${sendDate} ${sendTime}`, 'yyyy-LL-dd HH:mm', { zone: tz });
if (!/^\d{4}-\d{2}-\d{2}$/.test(sendDate) || !/^\d{2}:\d{2}$/.test(sendTime) || !sendAt.isValid) {
  return alert('invalid_send_datetime', 'paused', 'send_date must be yyyy-mm-dd and send_time HH:mm (24-hour, Asia/Kathmandu).');
}

// ---------- 4. live-mode configuration ----------
if (!dryRun) {
  if (isPlaceholder(cfg.textbeeDeviceId)) {
    return alert('config_textbee_device_id_not_set', 'paused', 'textbeeDeviceId is not configured (live mode requires a pinned TextBee device).');
  }
  const baseUrl = str(cfg.textbeeBaseUrl);
  if (!/^https:\/\/[^\s/]+(\/[^\s]*)?$/.test(baseUrl) || baseUrl.endsWith('/')) {
    return alert('config_textbee_base_url_invalid', 'paused', 'textbeeBaseUrl must start with https:// and have no trailing slash.');
  }
  const sim = str(cfg.textbeeSimSubscriptionId);
  if (sim !== '' && !/^\d+$/.test(sim)) {
    return alert('config_sim_subscription_id_invalid', 'paused', 'textbeeSimSubscriptionId must be blank or a whole number.');
  }
}

// ---------- 5. message build + validation ----------
const TEMPLATES = {
  'ne-latn': 'Happy Dashain! {school_name} ko tarfa bata sabai abhibhawak, vidyarthi ra shikshakharuma Bada Dashain ko hardik mangalmaya shubhakamana. Chutti: {holiday_start} dekhi {holiday_end} samma. School {reopen_date} dekhi khulchha. Dhanyabad, {school_name}.',
  'en': 'Happy Dashain! On behalf of {school_name}, warm Bada Dashain wishes to all parents, students and teachers. Holiday: {holiday_start} to {holiday_end}. School reopens on {reopen_date}. Thank you, {school_name}.',
  'ne-deva': 'शुभ दशैं! {school_name} तर्फबाट सबै अभिभावक, विद्यार्थी र शिक्षकलाई बडा दशैंको हार्दिक शुभकामना। बिदा: {holiday_start} देखि {holiday_end}। विद्यालय {reopen_date} मा खुल्छ। धन्यवाद।',
};
const LANG = {
  'en': 'en', 'english': 'en',
  'ne-latn': 'ne-latn', 'roman nepali': 'ne-latn', 'romanized nepali': 'ne-latn', 'roman_nepali': 'ne-latn',
  'ne-deva': 'ne-deva', 'nepali': 'ne-deva', 'devanagari': 'ne-deva',
};
const lang = LANG[str(c.message_language || 'ne-latn').toLowerCase()];
if (!lang) return alert('message_language_invalid', 'paused', 'message_language must be one of: ne-latn, en, ne-deva.');

const fmtField = (v) => {
  if (typeof v === 'number' && isFinite(v) && v > 20000) { // looks like a Sheets serial date
    return DateTime.fromMillis(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000, { zone: 'utc' }).toFormat('d LLL yyyy');
  }
  return str(v);
};
const vars = {
  school_name: fmtField(c.school_name), holiday_start: fmtField(c.holiday_start),
  holiday_end: fmtField(c.holiday_end), reopen_date: fmtField(c.reopen_date),
};
let template = str(c.message) || str(c.message_template_override) || TEMPLATES[lang];
const used = [...template.matchAll(/\{([a-z_]+)\}/g)].map((m) => m[1]);
for (const name of used) {
  if (!(name in vars)) return alert('message_unknown_placeholder', 'paused', `Template uses unknown placeholder {${name}}. Allowed: school_name, holiday_start, holiday_end, reopen_date.`);
  if (!vars[name]) return alert('message_field_missing', 'paused', `Campaigns column "${name}" is empty but the message template needs it.`);
}
let message = template.replace(/\{([a-z_]+)\}/g, (_, k) => vars[k]);
// normalise whitespace / control characters
message = message.replace(/[\u0000-\u0009\u000B-\u001F\u007F]/g, ' ').replace(/[ \t]+/g, ' ').trim();
if (lang !== 'ne-deva') { // keep Latin messages GSM-7 friendly (smart quotes etc. would force UCS-2)
  message = message.replace(/[\u2018\u2019\u201B]/g, "'").replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, '-').replace(/\u2026/g, '...').replace(/\u00A0/g, ' ');
}
if (!message) return alert('message_empty', 'paused', 'Message is empty after template substitution.');

// GSM 03.38 (basic + extension table) length / UCS-2 fallback
const GSM_BASIC = new Set(Array.from("@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà"));
const GSM_EXT = new Set(Array.from('\f^{}\\[~]|€'));
let septets = 0; let isGsm = true;
for (const ch of Array.from(message)) {
  if (GSM_BASIC.has(ch)) septets += 1; else if (GSM_EXT.has(ch)) septets += 2; else { isGsm = false; break; }
}
const encoding = isGsm ? 'GSM-7' : 'UCS-2';
const length = isGsm ? septets : message.length; // UCS-2 length = UTF-16 code units
const segments = isGsm ? (length <= 160 ? 1 : Math.ceil(length / 153)) : (length <= 70 ? 1 : Math.ceil(length / 67));
const maxSeg = Number(cfg.maxSmsSegments ?? 3);
if (segments > maxSeg) {
  return alert('message_too_long', 'paused',
    `Message needs ${segments} SMS segments (${encoding}, ${length} units); limit is ${maxSeg}. Shorten it or raise maxSmsSegments (carrier charges per segment).`);
}

// ---------- 6. send window ----------
const grace = Number(cfg.sendWindowGraceMinutes ?? 360);
const windowEnd = sendAt.plus({ minutes: grace });
const bypass = dryRun && cfg.bypassTimeGateInDryRun === true; // bypass is ONLY honoured in dry-run
const timing = { sendAtIso: sendAt.toISO(), windowEndIso: windowEnd.toISO() };
if (!bypass) {
  if (now < sendAt) return quiet('before_send_time', timing);
  if (now > windowEnd) {
    return alert('window_expired', 'expired',
      `Send window ended ${windowEnd.toISO()} before the campaign completed. Review the Contacts sheet; if still appropriate, set a new send_date/send_time and re-approve.`);
  }
}

return [{ json: {
  ...base, proceed: true, reason: bypass ? 'dry_run_time_gate_bypassed' : 'ok',
  ...timing, message, messageEncoding: encoding, messageLength: length, messageSegments: segments, messageLanguage: lang,
} }];

const cfg = $('Workflow Config').first().json;
const gate = $('Campaign Gate').first().json;
const lock = $('Verify Lock').first().json;

const campaignId = gate.campaignId;
const dryRun = gate.dryRun;

if (String(lock.last_run_id ?? '') !== gate.runId) {
  throw new Error('Campaign lock mismatch. Aborting.');
}
if (!dryRun && String(lock.status ?? '').toLowerCase() !== 'running') {
  throw new Error('Campaign status is not running. Aborting.');
}

const str = v => String(v ?? '').trim();
const nonEmpty = r => r && Object.values(r).some(v => str(v) !== '');
const rows = $input.all().map(i => i.json).filter(nonEmpty);

if (!rows.length) {
  throw new Error('No Contacts rows received.');
}

const allowedTypes = str(cfg.allowedRecipientTypes || 'parent,teacher,student')
  .toLowerCase().split(',').map(s => s.trim()).filter(Boolean);

const OPT_OUT = ['no','n','false','opt-out','optout','opt_out','opted-out','opted_out','unsubscribe','unsubscribed','stop','revoked','withdrawn'];

function normalizePhone(raw) {
  const s = str(raw);
  if (!s || !/^[+\d\s().-]+$/.test(s) || (s.indexOf('+') > 0)) {
    return { ok: false, code: 'phone_invalid' };
  }
  let digits = s.replace(/\D/g, '');
  let intl = s.startsWith('+');
  if (!intl && digits.startsWith('00')) {
    digits = digits.slice(2);
    intl = true;
  }
  if (!intl) {
    if (/^977\d{10}$/.test(digits)) intl = true;
    else if (cfg.normalizeLocalNepalNumbers !== false && /^9[678]\d{8}$/.test(digits)) {
      digits = '977' + digits;
      intl = true;
    } else return { ok: false, code: 'phone_country_code_missing' };
  }
  if (!/^[1-9]\d{7,14}$/.test(digits)) return { ok: false, code: 'phone_invalid_length' };
  if (digits.startsWith('977') && !/^9[678]\d{8}$/.test(digits.slice(3))) {
    return { ok: false, code: 'phone_nepal_not_mobile' };
  }
  return { ok: true, e164: '+' + digits };
}

const mask = e => e.slice(0,4) + '*'.repeat(Math.max(0,e.length-8)) + e.slice(-4);

const counts = {
  rows_read: rows.length, missing_contact_id: 0, already_processed: 0,
  skipped_total: 0, skipped: {}, eligible_total: 0,
  to_send_this_run: 0, deferred: 0
};

const keyCount = {};
for (const r of rows) {
  const id = str(r.contact_id);
  if (!id) continue;
  const k = `${campaignId}|${id}`;
  keyCount[k] = (keyCount[k] || 0) + 1;
}
if (Object.values(keyCount).some(n => n > 1)) {
  throw new Error('Duplicate contact_id rows detected. Fix Contacts sheet first.');
}

const HANDLED = ['processing','accepted','delivered','unknown'];
const handledPhones = new Set();

for (const r of rows) {
  if (HANDLED.includes(str(r.send_status).toLowerCase())) {
    const p = normalizePhone(r.phone);
    if (p.ok) handledPhones.add(p.e164);
  }
}

const sends = [];
const skips = [];
const alreadyProcessedRows = [];
const seenPhones = new Set();

function skip(r, reason) {
  counts.skipped[reason] = (counts.skipped[reason] || 0) + 1;
  counts.skipped_total++;
  skips.push({
    action: 'skip',
    row_number: r.row_number,
    contact_id: str(r.contact_id),
    campaign_id: campaignId,
    send_status: 'skipped',
    error_message: reason
  });
}

for (const r of rows) {
  const id = str(r.contact_id);
  if (!id) {
    counts.missing_contact_id++;
    continue;
  }

  const st = str(r.send_status).toLowerCase();

  if (st !== '' && st !== 'pending') {
    counts.already_processed++;
    alreadyProcessedRows.push({
      row_number: r.row_number,
      contact_id: id,
      send_status: st,
      has_provider_message_id: Boolean(str(r.provider_message_id)),
      has_sent_at: Boolean(str(r.sent_at)),
      error_message: str(r.error_message)
    });
    continue;
  }

  const consent = str(r.consent).toLowerCase();
  if (consent !== 'yes') {
    skip(r, OPT_OUT.includes(consent) ? 'opted_out' : 'consent_not_yes');
    continue;
  }

  if (!allowedTypes.includes(str(r.recipient_type).toLowerCase())) {
    skip(r, 'invalid_recipient_type');
    continue;
  }

  const p = normalizePhone(r.phone);
  if (!p.ok) {
    skip(r, p.code);
    continue;
  }

  if (handledPhones.has(p.e164) || seenPhones.has(p.e164)) {
    skip(r, 'duplicate_phone');
    continue;
  }

  seenPhones.add(p.e164);
  sends.push({
    row_number: r.row_number,
    contact_id: id,
    phone: p.e164,
    recipient_type: str(r.recipient_type).toLowerCase()
  });
}

counts.eligible_total = sends.length;
const cap = Math.max(0, Math.floor(Number(cfg.maxRecipientsPerRun ?? 1)));
const batch = sends.slice(0, cap);
counts.to_send_this_run = batch.length;
counts.deferred = sends.length - batch.length;

const out = [];
for (const s of skips) {
  out.push({ json: {
    ...s, planCounts: counts, alreadyProcessedRows,
    runId: gate.runId, dryRun
  }});
}

for (const s of batch) {
  const requestBody = { recipients: [s.phone], message: gate.message };
  const deviceId = str(cfg.textbeeDeviceId);

  if (deviceId && !/^REPLACE/i.test(deviceId)) {
    requestBody.deviceId = deviceId;
  }

  const simId = str(cfg.textbeeSimSubscriptionId);
  if (simId !== '' && Number.isFinite(Number(simId))) {
    requestBody.simSubscriptionId = Number(simId);
  }

  out.push({ json: {
    action: 'send',
    row_number: s.row_number,
    contact_id: s.contact_id,
    campaign_id: campaignId,
    recipient_type: s.recipient_type,
    phone: s.phone,
    phoneMasked: mask(s.phone),
    idempotencyKey: `${campaignId}|${s.contact_id}`,
    requestBody,
    planCounts: counts,
    alreadyProcessedRows,
    runId: gate.runId,
    dryRun
  }});
}

if (batch.length === 0) {
  out.push({ json: {
    action: 'nothing_to_send',
    campaign_id: campaignId,
    planCounts: counts,
    alreadyProcessedRows,
    runId: gate.runId,
    dryRun
  }});
}

return out;

// DRY RUN REPORT  (Code node, "Run Once for All Items")
// Logs what WOULD happen. No SMS is sent and no Contacts row is changed in a dry run.

const cfg = $('Workflow Config').first().json;
const gate = $('Campaign Gate').first().json;
const tz = String(cfg.timezone || 'Asia/Kathmandu');
const nowIso = DateTime.now().setZone(tz).toFormat("yyyy-LL-dd'T'HH:mm:ssZZ");

const items = $input.all().map((i) => i.json);
const plan = items[0].planCounts;
const sends = items.filter((x) => x.action === 'send');
const skipReasons = Object.entries(plan.skipped).map(([k, v]) => `${k}=${v}`).join(', ') || 'none';
const intended = sends.map((s) => `${s.contact_id}(${s.phoneMasked})`).join(', ') || 'none';
const note = (`DRY RUN - NO SMS SENT. Would send ${sends.length} now (eligible total ${plan.eligible_total}, deferred by cap ${plan.deferred}). ` +
  `Would mark skipped ${plan.skipped_total} [${skipReasons}]; already processed ${plan.already_processed}. ` +
  `Message (${gate.messageEncoding}, ${gate.messageSegments} segment(s)): "${gate.message}" | Intended: ${intended}`).slice(0, 1800);

return [{ json: {
  dryRunReport: { wouldSend: sends.length, eligibleTotal: plan.eligible_total, skipped: plan.skipped, intended: sends.map((s) => ({ contact_id: s.contact_id, phone: s.phoneMasked })) },
  runLog: {
    logged_at: nowIso, run_id: gate.runId, event: 'dry_run', campaign_id: gate.campaignId, dry_run: 'yes',
    rows_read: plan.rows_read, planned_sends: sends.length, attempted: 0, accepted: 0, failed: 0, unknown: 0,
    skipped_marked: 0, deferred: plan.deferred, message_encoding: gate.messageEncoding, message_segments: gate.messageSegments, note,
  },
} }];

// GUARD ROW  (Code node, "Run Once for All Items")  - compare-and-set check run immediately BEFORE each send.
// The Contacts row is re-read (filtered by contact_id AND campaign_id). We only proceed if, right now:
//   - exactly one row exists, - status is still blank/pending, - consent is still "yes", - phone still maps to the planned number.
// This also protects against sheet edits / row shifts since planning, and honours opt-outs made mid-run.

const cfg = $('Workflow Config').first().json;
const planned = $('Loop Over Recipients').first().json;   // current iteration (batch size 1)
const str = (v) => String(v ?? '').trim();
const nonEmpty = (r) => r && Object.values(r).some((v) => str(v) !== '');
const rows = $input.all().map((i) => i.json).filter(nonEmpty);

function normalizePhone(raw) {
  const s = str(typeof raw === 'number' ? String(raw) : raw);
  if (!s) return { ok: false, code: 'phone_empty' };
  if (!/^[+\d\s().-]+$/.test(s) || s.lastIndexOf('+') > 0) return { ok: false, code: 'phone_invalid_characters' };
  let digits = s.replace(/\D/g, '');
  let intl = s.startsWith('+');
  if (!intl && s.startsWith('00')) { digits = digits.slice(2); intl = true; }
  if (!intl) {
    if (/^977\d{10}$/.test(digits)) intl = true;                                         // 977XXXXXXXXXX without +
    else if (cfg.normalizeLocalNepalNumbers !== false && /^9[678]\d{8}$/.test(digits)) { digits = '977' + digits; intl = true; } // local Nepal mobile
    else return { ok: false, code: 'phone_missing_country_code' };
  }
  if (!/^[1-9]\d{7,14}$/.test(digits)) return { ok: false, code: 'phone_invalid_length' };
  if (digits.startsWith('977') && !/^9[678]\d{8}$/.test(digits.slice(3))) return { ok: false, code: 'phone_nepal_not_mobile' };
  return { ok: true, e164: '+' + digits };
}

const fail = (reason) => [{ json: { eligible: false, send_status: 'skipped', guardReason: reason, contact_id: planned.contact_id, campaign_id: planned.campaign_id } }];
if (rows.length === 0) return fail('row_not_found_at_send_time');
if (rows.length > 1) return fail('multiple_rows_at_send_time');
const r = rows[0];
if (str(r.contact_id) !== planned.contact_id || str(r.campaign_id) !== planned.campaign_id) return fail('row_identity_mismatch');
const st = str(r.send_status).toLowerCase();
if (st !== '' && st !== 'pending') return fail('status_changed_to_' + st);
if (str(r.consent).toLowerCase() !== 'yes') return fail('consent_no_longer_yes');
const p = normalizePhone(r.phone);
if (!p.ok || p.e164 !== planned.phone) return fail('phone_changed_since_planning');
if (!r.row_number) return fail('row_number_missing');

return [{ json: { eligible: true, row_number: r.row_number, contact_id: planned.contact_id, campaign_id: planned.campaign_id,
  idempotencyKey: planned.idempotencyKey, phoneMasked: planned.phoneMasked } }];

// CLASSIFY RESPONSE  (Code node, "Run Once for Each Item")
// Turns the raw HTTP result into a per-recipient outcome. Never retries.
//   accepted : TextBee returned success + smsBatchId  (= queued for the phone, NOT delivery)
//   failed   : provider definitively refused (401 / 404 / 429) - nothing was sent
//   unknown  : outcome ambiguous (timeout, network error, 5xx, other 4xx, 200 without batch id)
//              -> NEVER auto-resent; needs manual review or the reconcile workflow.
// Any outcome other than "accepted" halts the run (fatal) so problems cannot snowball.

const cfg = $('Workflow Config').first().json;
const orig = $('Loop Over Recipients').first().json;      // current iteration (batch size 1)
const guard = $('Guard Row').first().json;
const j = $json;
const tz = String(cfg.timezone || 'Asia/Kathmandu');

// redact anything that looks like a phone number, token or e-mail; truncate
const clean = (v) => String(v ?? '')
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[redacted]')
  .replace(/[A-Za-z0-9_\-]{32,}/g, '[redacted]')
  .replace(/\+?\d[\d\s\-()]{6,}\d/g, '[redacted]')
  .replace(/\s+/g, ' ').trim().slice(0, 160);

let send_status = 'unknown'; let provider_message_id = ''; let sent_at = ''; let error_message = '';
let fatal = true; let fatalReason = ''; const sc = j.statusCode;

if (typeof sc === 'number') {
  const body = j.body && typeof j.body === 'object' ? j.body : {};
  const data = body.data && typeof body.data === 'object' ? body.data : {};
  const apiMsg = clean(body.message || body.error || data.message || data.error || '');
  const hasBatch = typeof data.smsBatchId === 'string' && data.smsBatchId.trim() !== '';
  const queued = (sc === 200 || sc === 201) && data.success === true && hasBatch;
  const immediate = (sc === 200 || sc === 201) &&
    (Number.isFinite(Number(data.successCount)) || Number.isFinite(Number(data.failureCount)));
  if (queued) {
    send_status = 'accepted';
    provider_message_id = data.smsBatchId;
    sent_at = DateTime.now().setZone(tz).toFormat("yyyy-LL-dd'T'HH:mm:ssZZ");
    error_message = data.warning && data.warning.message ? 'Provider warning: ' + clean(data.warning.message) : '';
    fatal = false;
  } else if (immediate && Number(data.successCount) > 0 && Number(data.failureCount || 0) === 0) {
    send_status = 'accepted';
    provider_message_id = String(data.smsBatchId || data.messageId || '');
    sent_at = DateTime.now().setZone(tz).toFormat("yyyy-LL-dd'T'HH:mm:ssZZ");
    error_message = 'TextBee reports immediate dispatch success; delivery is not confirmed.';
    fatal = false;
  } else if (immediate && Number(data.successCount || 0) === 0 && Number(data.failureCount || 0) > 0) {
    send_status = 'failed';
    error_message = `TextBee immediate dispatch reported failureCount=${Number(data.failureCount)}; ${apiMsg || 'check provider response'}`;
    fatalReason = 'TextBee reported no successful dispatch';
  } else if (sc === 400 || sc === 401 || sc === 404 || sc === 429) {
    send_status = 'failed';
    error_message = `HTTP ${sc}: ${apiMsg || 'TextBee rejected the request'}`;
    fatalReason = `TextBee request rejected (HTTP ${sc})`;
  } else {
    send_status = 'unknown';
    error_message = `HTTP ${sc}: ${apiMsg || 'response does not prove acceptance or failure'} - verify in TextBee before any resend`;
    fatalReason = `TextBee response ambiguous (HTTP ${sc})`;
  }
} else {
  const raw = j.error && typeof j.error === 'object' ? (j.error.message || j.error.description || '') : (j.error || '');
  send_status = 'unknown';
  error_message = `Network/timeout error: ${clean(raw) || 'no response'} - message may already have been queued; verify in TextBee before any resend`;
  fatalReason = 'Network or timeout error calling TextBee (outcome unknown)';
}
return { json: {
  row_number: guard.row_number, contact_id: orig.contact_id, campaign_id: orig.campaign_id, idempotencyKey: orig.idempotencyKey, phoneMasked: orig.phoneMasked,
  send_status, provider_message_id, sent_at, error_message, httpStatus: typeof sc === 'number' ? sc : 0, fatal, fatalReason,
} };

// RESTORE RESULT ITEM  (Code node, "Run Once for Each Item")
// The Google Sheets update returns the row, not our classification. Re-emit the classification
// so the loop collects it and downstream nodes see { send_status, fatal, ... }.
return { json: $('Classify Response').first().json };

// SUMMARIZE RUN  (Code node, "Run Once for All Items")  - live runs only
// Builds the new campaign status and the RunLog row. Counts "accepted" = queued by TextBee, NOT delivered.

const cfg = $('Workflow Config').first().json;
const gate = $('Campaign Gate').first().json;
const plan = $('Plan Recipients').first().json.planCounts;
const tz = String(cfg.timezone || 'Asia/Kathmandu');
const nowIso = DateTime.now().setZone(tz).toFormat("yyyy-LL-dd'T'HH:mm:ssZZ");

const results = $input.all().map((i) => i.json).filter((r) => r && r.send_status);
const n = (s) => results.filter((r) => r.send_status === s).length;
const accepted = n('accepted'), failed = n('failed'), unknown = n('unknown');

const remaining = plan.deferred;
const newStatus = remaining > 0 ? 'approved' : 'completed';
const note = `Run ${gate.runId}: attempted ${results.length}, accepted ${accepted} (queued by TextBee, not proof of delivery), failed ${failed}, unknown ${unknown}, skipped ${plan.skipped_total}, still pending ${remaining}.` +
  (remaining > 0 ? ' Next scheduled run continues while inside the send window.' : '') +
  (failed + unknown > 0 ? ' REVIEW failed/unknown rows before any manual reset.' : '');

return [{ json: {
  campaign_id: gate.campaignId, status: newStatus, status_note: note.slice(0, 480), last_run_id: gate.runId, last_run_at: nowIso,
  runLog: {
    logged_at: nowIso, run_id: gate.runId, event: 'live_run', campaign_id: gate.campaignId, dry_run: 'no',
    rows_read: plan.rows_read, planned_sends: plan.to_send_this_run, attempted: results.length, accepted, failed, unknown,
    skipped_marked: plan.skipped_total, deferred: remaining,
    message_encoding: gate.messageEncoding, message_segments: gate.messageSegments, note: note.slice(0, 480),
  },
} }];
